```php
<?php

function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        if ($order == 'asc') {
            return ($a['age'] - $b['age']);
        } else {
            return ($b['age'] - $a['age']);
        }
    });

    return $set;
}

// Example usage:
