```go
package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"

	"github.com/mitchellh/go-homedir"
)

type StructSchema struct {
	Name    string
	Schema  string
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ", os.Args[0], "<source_file_name>.go <struct_name>")
		return
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	// Ensure the directory exists where the schema files will be saved
	schemaDir := filepath.Join(homedir.HomeDir(), "schemas")
	os.MkdirAll(schemaDir, 0755)
	schemaPath := filepath.Join(schemaDir, fmt.Sprintf("%s.avsc", structName))

	// Parse the source file
	file, err := parser.ParseFile(token.NewFileSet(), sourceFileName, nil, parser.AllErrors)
	if err != nil {
		log.Fatalf("Failed to parse %v: %v", sourceFileName, err)
	}
	ast.Inspect(file, func(n ast.Node) bool {
		if node, ok := n.(*ast.StructType); ok && node.Name == structName {
			var schemaStruct = &StructSchema{
				Name:    structName,
				Schema:  getAvroSchema(node),
			}
			err := ioutil.WriteFile(schemaPath, []byte(schemaStruct.Schema), 0644)
			if err != nil {
				log.Fatalf("Failed to write schema to %v: %v", schemaPath, err)
			}
			fmt.Printf("Generated Avro schema for struct %v at %v\n", structName, schemaPath)
		}
		return true
	})
}

// Function to create an Avro schema representation of a struct.
func getAvroSchema(node *ast.StructType) string {
	schema := `{"name": "%s","namespace":"com.example","fields":[{"name":"field_1","type":"int"}],"type":"record"}` %
		node.Name.Name
	return schema
}
```

### How to Use:

1. **Compile the Program**: Save this code as a `.go` file (e.g., `generate_avro_schema.go`) and compile it using `go build`.

   ```sh
   go build -o generate_avro_schema ./generate_avro_schema.go
   ```

2. **Run the Program**: Pass the path to your Go source file and the name of the struct you want to convert as arguments when running the compiled binary.

   ```sh
   ./generate_avro_schema my_struct.go MyStruct
   ```

This script will scan the provided Go source file, find any structs with the specified name (`MyStruct` in the example above), and generate an Avro schema for those structs. The resulting schema files will be placed in a directory called `schemas` under your home directory.

