    <meta charset="UTF-8">
    <title>Sun Appearance</title>
    <style>
        .sun {
            width: 50px;
            height: 50px;
            background-color: #fff;
            border-radius: 50%;
            position: absolute;
        }
        .day {
            left: 25px;
            top: 25px;
            animation: shine 3s infinite alternate;
        }
        @keyframes shine {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }
        .night {
            left: 75px;
            top: 75px;
            opacity: 0;
        }
    </style>
</head>
